{"file_path":"src/address.js","content":"/**
 * Cell addresses. A column is one or two letters (`A`..`Z`, then `AA`..`ZZ`)
 * and a row is one to three digits naming a row of at least 1.
 */

const ADDRESS = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Parse `text` as an address, or return null when it names no cell. */
export function parseAddress(text) {
  const match = ADDRESS.exec(text)
  if (match === null) return null
  const letters = match[1].toUpperCase()
  let col = 0
  for (const letter of letters) col = col * 26 + (letter.charCodeAt(0) - 64)
  const row = Number(match[2])
  if (row < 1) return null
  return { col, row, name: letters + String(row) }
}

/** The canonical name of the cell at `col` and `row`. */
export function addressName(col, row) {
  let letters = ''
  let n = col
  while (n > 0) {
    const rem = (n - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    n = (n - rem - 1) / 26
  }
  return letters + String(row)
}

/** Order two cells by column and then by row. */
export function compareCells(a, b) {
  return a.col - b.col || a.row - b.row
}
"}

