{"file_path":"src/value.js","content":"/** Values: numbers, text, booleans and errors, and the ways they mix. */

export const ERROR_TOKENS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']

export const number = (n) => ({ kind: 'number', number: n })
export const text = (s) => ({ kind: 'text', text: s })
export const boolean = (b) => ({ kind: 'boolean', boolean: b })
export const error = (token) => ({ kind: 'error', token })

export const ZERO = number(0)
export const DIV0 = error('#DIV/0!')
export const REF = error('#REF!')
export const VALUE = error('#VALUE!')
export const CYCLE = error('#CYCLE!')
export const NAME = error('#NAME?')
export const ERR = error('#ERR!')

export const isError = (value) => value.kind === 'error'

const LITERAL_NUMBER = /^-?[0-9]+(\.[0-9]+)?$/

/** Read the content of a cell that is not a formula. */
export function literalValue(content) {
  if (content === '') return ZERO
  if (LITERAL_NUMBER.test(content)) return number(Number(content))
  if (ERROR_TOKENS.includes(content)) return error(content)
  return text(content)
}

/** Read `value` in an arithmetic position: booleans count, text does not. */
export function asNumber(value) {
  if (value.kind === 'number') return value
  if (value.kind === 'boolean') return number(value.boolean ? 1 : 0)
  if (value.kind === 'error') return value
  return VALUE
}

/** Every arithmetic result must be finite. */
export function finite(n) {
  return Number.isFinite(n) ? number(n) : DIV0
}

const RANK = { number: 0, text: 1, boolean: 2 }

function compareText(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const shared = Math.min(left.length, right.length)
  for (let i = 0; i < shared; i += 1) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return left.length - right.length === 0 ? 0 : left.length < right.length ? -1 : 1
}

/** Order two non-error values: numbers below text below booleans. */
export function compareValues(a, b) {
  if (RANK[a.kind] !== RANK[b.kind]) return RANK[a.kind] < RANK[b.kind] ? -1 : 1
  if (a.kind === 'number') return a.number === b.number ? 0 : a.number < b.number ? -1 : 1
  if (a.kind === 'text') return compareText(a.text, b.text)
  return a.boolean === b.boolean ? 0 : a.boolean ? 1 : -1
}

/** Print a number the way JavaScript would after rounding to ten digits. */
export function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  return String(Number(n.toPrecision(10)))
}

/** Print a value for the `values` mode. */
export function formatValue(value) {
  switch (value.kind) {
    case 'number':
      return formatNumber(value.number)
    case 'text':
      return value.text
    case 'boolean':
      return value.boolean ? 'TRUE' : 'FALSE'
    default:
      return value.token
  }
}
"}

