{"file_path":"src/formula.js","content":"/**
 * The formula grammar. `parseFormula` turns the body of a formula into a tree,
 * or returns null when the grammar does not accept it.
 */

const NUMBER = /[0-9]+(\.[0-9]+)?/y
const WORD = /[A-Za-z][A-Za-z0-9]*/y
const OPERATORS = ['<>', '<=', '>=', '^', '*', '/', '+', '-', '=', '<', '>', '(', ')', ',', ':']

/** Split a formula body into tokens, or return null on an unreadable character. */
function lex(source) {
  const tokens = []
  let i = 0
  while (i < source.length) {
    const ch = source[i]
    if (ch === ' ' || ch === '\t') {
      i += 1
      continue
    }
    NUMBER.lastIndex = i
    const digits = NUMBER.exec(source)
    if (digits !== null) {
      tokens.push({ kind: 'number', text: digits[0] })
      i = NUMBER.lastIndex
      continue
    }
    WORD.lastIndex = i
    const word = WORD.exec(source)
    if (word !== null) {
      tokens.push({ kind: 'word', text: word[0] })
      i = WORD.lastIndex
      continue
    }
    const operator = OPERATORS.find((op) => source.startsWith(op, i))
    if (operator === undefined) return null
    tokens.push({ kind: 'operator', text: operator })
    i += operator.length
  }
  return tokens
}

const COMPARISONS = ['=', '<>', '<', '<=', '>', '>=']

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek(offset = 0) {
    return this.tokens[this.at + offset]
  }

  isOperator(text, offset = 0) {
    const token = this.peek(offset)
    return token !== undefined && token.kind === 'operator' && token.text === text
  }

  take() {
    const token = this.tokens[this.at]
    this.at += 1
    return token
  }

  /** comparison := additive ((= | <> | < | <= | > | >=) additive)*, left grouped */
  expression() {
    let left = this.additive()
    if (left === null) return null
    while (this.peek() !== undefined && this.peek().kind === 'operator' && COMPARISONS.includes(this.peek().text)) {
      const op = this.take().text
      const right = this.additive()
      if (right === null) return null
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  /** additive := multiplicative ((+ | -) multiplicative)*, left grouped */
  additive() {
    let left = this.multiplicative()
    if (left === null) return null
    while (this.isOperator('+') || this.isOperator('-')) {
      const op = this.take().text
      const right = this.multiplicative()
      if (right === null) return null
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  /** multiplicative := power ((* | /) power)*, left grouped */
  multiplicative() {
    let left = this.power()
    if (left === null) return null
    while (this.isOperator('*') || this.isOperator('/')) {
      const op = this.take().text
      const right = this.power()
      if (right === null) return null
      left = { kind: 'binary', op, left, right }
    }
    return left
  }

  /** power := unary (^ power)?, right grouped, so a leading sign binds tighter */
  power() {
    const left = this.unary()
    if (left === null) return null
    if (!this.isOperator('^')) return left
    this.take()
    const right = this.power()
    if (right === null) return null
    return { kind: 'binary', op: '^', left, right }
  }

  /** unary := (- | +) unary | primary */
  unary() {
    if (this.isOperator('-') || this.isOperator('+')) {
      const op = this.take().text
      const operand = this.unary()
      if (operand === null) return null
      return { kind: 'unary', op, operand }
    }
    return this.primary()
  }

  primary() {
    const token = this.peek()
    if (token === undefined) return null
    if (token.kind === 'number') {
      this.take()
      return { kind: 'number', value: Number(token.text) }
    }
    if (this.isOperator('(')) {
      this.take()
      const inner = this.expression()
      if (inner === null) return null
      if (!this.isOperator(')')) return null
      this.take()
      return { kind: 'group', inner }
    }
    if (token.kind === 'word') {
      if (this.isOperator('(', 1)) return this.call()
      if (this.isOperator(':', 1)) {
        const second = this.peek(2)
        if (second === undefined || second.kind !== 'word') return null
        this.take()
        this.take()
        this.take()
        return { kind: 'range', from: token.text, to: second.text }
      }
      this.take()
      const upper = token.text.toUpperCase()
      if (upper === 'TRUE') return { kind: 'boolean', value: true }
      if (upper === 'FALSE') return { kind: 'boolean', value: false }
      return { kind: 'reference', text: token.text }
    }
    return null
  }

  call() {
    const name = this.take().text
    this.take()
    const args = []
    if (this.isOperator(')')) {
      this.take()
      return { kind: 'call', name, args }
    }
    for (;;) {
      const argument = this.expression()
      if (argument === null) return null
      args.push(argument)
      if (this.isOperator(',')) {
        this.take()
        continue
      }
      if (this.isOperator(')')) {
        this.take()
        return { kind: 'call', name, args }
      }
      return null
    }
  }
}

/** Parse the body of a formula, or return null when the grammar refuses it. */
export function parseFormula(body) {
  const tokens = lex(body)
  if (tokens === null) return null
  const parser = new Parser(tokens)
  const tree = parser.expression()
  if (tree === null || parser.at !== tokens.length) return null
  return tree
}
"}

