{"file_path":"src/sheet.js","content":"/** Reading a sheet from its text. */

import { parseAddress, compareCells } from './address.js'

export class SheetError extends Error {}

/**
 * Read the text of a sheet into cells, in the order they should be printed.
 * Throws a SheetError carrying the message of the first failure.
 */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const cells = new Map()
  for (let index = 0; index < lines.length; index += 1) {
    const number = index + 1
    const line = lines[index].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue
    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end += 1
    const written = line.slice(0, end)
    let rest = end
    while (rest < line.length && (line[rest] === ' ' || line[rest] === '\t')) rest += 1
    const content = line.slice(rest)
    const address = parseAddress(written)
    if (address === null) {
      throw new SheetError(`line ${number}: invalid cell address ${written}`)
    }
    if (cells.has(address.name)) {
      throw new SheetError(`line ${number}: cell ${address.name} is declared twice`)
    }
    cells.set(address.name, { ...address, content })
  }
  const order = [...cells.values()].sort(compareCells)
  return { cells, order }
}
"}

