import { parseAddress, addressName, compareCells } from './address.js'
import { parseFormula } from './formula.js'
import * as V from './value.js'

const VARIADIC = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
const FUNCTIONS = [...VARIADIC, 'ABS', 'IF']

/** The cells a range covers, in ascending column and then row order. */
function rangeCells(node) {
  const from = parseAddress(node.from)
  const to = parseAddress(node.to)
  if (from === null || to === null) return null
  const cells = []
  const firstCol = Math.min(from.col, to.col)
  const lastCol = Math.max(from.col, to.col)
  const firstRow = Math.min(from.row, to.row)
  const lastRow = Math.max(from.row, to.row)
  for (let col = firstCol; col <= lastCol; col += 1) {
    for (let row = firstRow; row <= lastRow; row += 1) {
      cells.push({ col, row, name: addressName(col, row) })
    }
  }
  return cells
}

export class Sheet {
  constructor(parsed) {
    this.cells = parsed.cells
    this.order = parsed.order
    this.values = new Map()
    this.running = new Set()
    this.trees = new Map()
  }

  /** The tree of a cell's formula, null when the grammar refused it. */
  tree(cell) {
    if (!this.trees.has(cell.name)) {
      this.trees.set(cell.name, cell.content.startsWith('=') ? parseFormula(cell.content.slice(1)) : null)
    }
    return this.trees.get(cell.name)
  }

  /** The value of the named cell; cells nobody declared read as zero. */
  value(name) {
    if (this.values.has(name)) return this.values.get(name)
    const cell = this.cells.get(name)
    if (cell === undefined) return V.ZERO
    if (this.running.has(name)) return V.CYCLE
    this.running.add(name)
    let value
    try {
      if (!cell.content.startsWith('=')) {
        value = V.literalValue(cell.content)
      } else {
        const tree = this.tree(cell)
        value = tree === null ? V.ERR : this.eval(tree)
      }
    } finally {
      this.running.delete(name)
    }
    this.values.set(name, value)
    return value
  }

  eval(node) {
    switch (node.kind) {
      case 'number':
        return V.number(node.value)
      case 'boolean':
        return V.boolean(node.value)
      case 'group':
        return this.eval(node.inner)
      case 'range':
        // A range is only meaningful directly as a function argument.
        return V.ERR
      case 'reference': {
        const address = parseAddress(node.text)
        return address === null ? V.REF : this.value(address.name)
      }
      case 'unary':
        return this.unary(node)
      case 'binary':
        return this.binary(node)
      default:
        return this.call(node)
    }
  }

  unary(node) {
    const operand = V.asNumber(this.eval(node.operand))
    if (V.isError(operand)) return operand
