    const values = node.args.flatMap((argument) => this.argumentValues(argument))
    if (name === 'ABS' ? values.length !== 1 : values.length < 1) return V.ERR
    const failure = values.find(V.isError)
    if (failure !== undefined) return failure
    if (name === 'COUNT') return V.number(values.filter((value) => value.kind === 'number').length)
    const numbers = []
    for (const value of values) {
      const n = V.asNumber(value)
      if (V.isError(n)) return n
      numbers.push(n.number)
    }
    switch (name) {
      case 'SUM':
        return V.finite(numbers.reduce((total, n) => total + n, 0))
      case 'MIN':
        return V.finite(Math.min(...numbers))
      case 'MAX':
        return V.finite(Math.max(...numbers))
      case 'AVG':
        return V.finite(numbers.reduce((total, n) => total + n, 0) / numbers.length)
      default:
        return V.finite(Math.abs(numbers[0]))
    }
  }

  /** `IF` reads only the branch it takes, so the other one's errors stay unseen. */
  callIf(node) {
    if (node.args.length !== 3) return V.ERR
    const condition = this.single(node.args[0])
    if (V.isError(condition)) return condition
    let taken
    if (condition.kind === 'boolean') taken = condition.boolean
    else if (condition.kind === 'number') taken = condition.number !== 0
    else return V.VALUE
    return this.single(node.args[taken ? 1 : 2])
  }

  /** One argument read as a single value. */
  single(node) {
    const values = this.argumentValues(node)
    const failure = values.find(V.isError)
    if (failure !== undefined) return failure
    return values.length === 1 ? values[0] : V.ERR
  }

  /** The distinct cells a cell's content names directly, ranges expanded. */
  deps(cell) {
    if (!cell.content.startsWith('=')) return []
    const tree = this.tree(cell)
    if (tree === null) return []
    const found = new Map()
    const walk = (node) => {
      switch (node.kind) {
        case 'reference': {
          const address = parseAddress(node.text)
          if (address !== null) found.set(address.name, address)
          break
        }
        case 'range': {
          const cells = rangeCells(node)
          if (cells !== null) for (const one of cells) found.set(one.name, one)
          break
        }
        case 'group':
          walk(node.inner)
          break
        case 'unary':
          walk(node.operand)
          break
        case 'binary':
          walk(node.left)
          walk(node.right)
          break
        case 'call':
          for (const argument of node.args) walk(argument)
          break
        default:
          break
      }
    }
    walk(tree)
    return [...found.values()].sort(compareCells)
  }
}
"}

