{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Sheet } from './evaluate.js'
import { formatValue } from './value.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const argv = process.argv.slice(2)
  const mode = argv.length === 1 ? argv[0] : null
  if (mode !== 'values' && mode !== 'deps') fail('usage: cli.js values|deps')
  let parsed
  try {
    parsed = parseSheet(readInput())
  } catch (cause) {
    if (cause instanceof SheetError) fail(cause.message)
    throw cause
  }
  const sheet = new Sheet(parsed)
  const lines = parsed.order.map((cell) =>
    mode === 'values'
      ? `${cell.name}=${formatValue(sheet.value(cell.name))}`
      : `${cell.name}:${sheet.deps(cell).map((dep) => ` ${dep.name}`).join('')}`,
  )
  process.stdout.write(lines.map((line) => `${line}\n`).join(''))
}

main()
"}

